import Foundation

// A small JSON Schema (2020-12) validator for the vendored device contract
// (Contract/*.schema.json, generated by Attro from its Zod schemas). It knows
// exactly the keywords those files use and reports any other keyword as a
// violation, so a schema that starts using a new keyword fails the tests
// instead of being half-checked. No dependency: the package has none.

/// A JSON value, decoded strictly: a boolean is never a number.
enum JSONValue: Equatable, Decodable, CustomStringConvertible {
    case null
    case bool(Bool)
    case number(Double)
    case string(String)
    case array([JSONValue])
    case object([String: JSONValue])

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if container.decodeNil() {
            self = .null
        } else if let value = try? container.decode(Bool.self) {
            self = .bool(value)
        } else if let value = try? container.decode(Double.self) {
            self = .number(value)
        } else if let value = try? container.decode(String.self) {
            self = .string(value)
        } else if let value = try? container.decode([JSONValue].self) {
            self = .array(value)
        } else if let value = try? container.decode([String: JSONValue].self) {
            self = .object(value)
        } else {
            throw DecodingError.dataCorruptedError(in: container, debugDescription: "not a JSON value")
        }
    }

    static func parse(_ data: Data) throws -> JSONValue {
        try JSONDecoder().decode(JSONValue.self, from: data)
    }

    subscript(key: String) -> JSONValue? {
        if case .object(let members) = self { return members[key] }
        return nil
    }

    var stringValue: String? {
        if case .string(let value) = self { return value }
        return nil
    }

    var boolValue: Bool? {
        if case .bool(let value) = self { return value }
        return nil
    }

    var arrayValue: [JSONValue]? {
        if case .array(let value) = self { return value }
        return nil
    }

    var objectValue: [String: JSONValue]? {
        if case .object(let value) = self { return value }
        return nil
    }

    var typeName: String {
        switch self {
        case .null: return "null"
        case .bool: return "boolean"
        case .number: return "number"
        case .string: return "string"
        case .array: return "array"
        case .object: return "object"
        }
    }

    var description: String {
        switch self {
        case .null: return "null"
        case .bool(let value): return String(value)
        case .number(let value): return String(value)
        case .string(let value): return "\"\(value)\""
        case .array(let items): return "[\(items.map { $0.description }.joined(separator: ","))]"
        case .object(let members):
            let body = members.keys.sorted().map { "\"\($0)\":\(members[$0]!.description)" }
            return "{\(body.joined(separator: ","))}"
        }
    }
}

struct SchemaViolation: CustomStringConvertible, Equatable {
    let path: String
    let message: String
    var description: String { "\(path): \(message)" }
}

enum JSONSchema {
    /// The keywords the vendored schemas use. Anything else is a violation.
    static let supportedKeywords: Set<String> = [
        "$schema", "$id", "description",
        "type", "enum", "const",
        "minLength", "maxLength", "pattern", "format",
        "minimum", "maximum",
        "properties", "required", "additionalProperties", "propertyNames",
        "items",
        "anyOf", "oneOf",
    ]

    /// Every violation of `value` against `schema`; empty when it is valid.
    static func violations(of value: JSONValue, against schema: JSONValue, at path: String = "$") -> [SchemaViolation] {
        let keywords: [String: JSONValue]
        switch schema {
        case .bool(let allowsEverything):
            return allowsEverything ? [] : [SchemaViolation(path: path, message: "the false schema allows nothing")]
        case .object(let members):
            keywords = members
        default:
            return [SchemaViolation(path: path, message: "not a schema: \(schema)")]
        }

        var out: [SchemaViolation] = []
        for key in keywords.keys.sorted() where !supportedKeywords.contains(key) {
            out.append(SchemaViolation(path: path, message: "unsupported schema keyword \(key): extend JSONSchema"))
        }

        if let type = keywords["type"] {
            out += checkType(value, type, path)
        }
        if let options = keywords["enum"] {
            if let list = options.arrayValue {
                if !list.contains(value) {
                    out.append(SchemaViolation(path: path, message: "\(value) is not one of \(options)"))
                }
            } else {
                out.append(SchemaViolation(path: path, message: "enum is not an array"))
            }
        }
        if let constant = keywords["const"], constant != value {
            out.append(SchemaViolation(path: path, message: "\(value) is not \(constant)"))
        }

        if case .string(let text) = value {
            let length = Double(text.unicodeScalars.count)
            if case .number(let minimum)? = keywords["minLength"], length < minimum {
                out.append(SchemaViolation(path: path, message: "shorter than \(Int(minimum))"))
            }
            if case .number(let maximum)? = keywords["maxLength"], length > maximum {
                out.append(SchemaViolation(path: path, message: "longer than \(Int(maximum))"))
            }
            if let pattern = keywords["pattern"] {
                out += checkPattern(text, pattern, path)
            }
            if let format = keywords["format"] {
                out += checkFormat(text, format, path)
            }
        }

        if case .number(let number) = value {
            if case .number(let minimum)? = keywords["minimum"], number < minimum {
                out.append(SchemaViolation(path: path, message: "\(number) is below \(minimum)"))
            }
            if case .number(let maximum)? = keywords["maximum"], number > maximum {
                out.append(SchemaViolation(path: path, message: "\(number) is above \(maximum)"))
            }
        }

        if case .array(let items) = value, let itemSchema = keywords["items"] {
            for (index, item) in items.enumerated() {
                out += violations(of: item, against: itemSchema, at: "\(path)[\(index)]")
            }
        }

        if case .object(let members) = value {
            let properties = keywords["properties"]?.objectValue ?? [:]
            for required in keywords["required"]?.arrayValue ?? [] {
                if let name = required.stringValue, members[name] == nil {
                    out.append(SchemaViolation(path: path, message: "missing required property \(name)"))
                }
            }
            for name in members.keys.sorted() {
                let member = members[name]!
                if let propertySchema = properties[name] {
                    out += violations(of: member, against: propertySchema, at: "\(path).\(name)")
                } else if let additional = keywords["additionalProperties"] {
                    out += violations(of: member, against: additional, at: "\(path).\(name)")
                }
                if let names = keywords["propertyNames"] {
                    out += violations(of: .string(name), against: names, at: "\(path).\(name) (name)")
                }
            }
        }

        if let branches = keywords["anyOf"]?.arrayValue {
            if !branches.contains(where: { violations(of: value, against: $0, at: path).isEmpty }) {
                out.append(SchemaViolation(path: path, message: "matches none of the anyOf branches"))
            }
        }
        if let branches = keywords["oneOf"]?.arrayValue {
            let matching = branches.filter { violations(of: value, against: $0, at: path).isEmpty }.count
            if matching != 1 {
                out.append(SchemaViolation(path: path, message: "matches \(matching) oneOf branches, not exactly one"))
            }
        }
        return out
    }

    private static func checkType(_ value: JSONValue, _ type: JSONValue, _ path: String) -> [SchemaViolation] {
        let names: [String]
        switch type {
        case .string(let one):
            names = [one]
        case .array(let many):
            names = many.compactMap(\.stringValue)
        default:
            return [SchemaViolation(path: path, message: "invalid type keyword \(type)")]
        }
        if names.contains(where: { has(value, type: $0) }) { return [] }
        return [SchemaViolation(path: path, message: "expected \(names.joined(separator: " or ")), got \(value.typeName)")]
    }

    private static func has(_ value: JSONValue, type: String) -> Bool {
        switch (type, value) {
        case ("null", .null), ("boolean", .bool(_)), ("string", .string(_)), ("number", .number(_)),
             ("array", .array(_)), ("object", .object(_)):
            return true
        case ("integer", .number(let number)):
            return number.isFinite && number.rounded(.towardZero) == number
        default:
            return false
        }
    }

    private static func checkPattern(_ text: String, _ pattern: JSONValue, _ path: String) -> [SchemaViolation] {
        guard let source = pattern.stringValue,
              let regex = try? NSRegularExpression(pattern: source) else {
            return [SchemaViolation(path: path, message: "invalid pattern \(pattern)")]
        }
        let range = NSRange(text.startIndex..<text.endIndex, in: text)
        if regex.firstMatch(in: text, options: [], range: range) != nil { return [] }
        return [SchemaViolation(path: path, message: "\"\(text)\" does not match \(source)")]
    }

    private static func checkFormat(_ text: String, _ format: JSONValue, _ path: String) -> [SchemaViolation] {
        switch format.stringValue {
        case "uuid":
            return UUID(uuidString: text) != nil
                ? [] : [SchemaViolation(path: path, message: "\"\(text)\" is not a UUID")]
        default:
            return [SchemaViolation(path: path, message: "unsupported format \(format): extend JSONSchema")]
        }
    }
}
